// Extract story ID from chat message
const message = $input.first().json?.chatInput || $input.first().json?.message || '';
const storyId = message.trim().toUpperCase();

if (!storyId || !/^[A-Z]+-\d+$/.test(storyId)) {
  throw new Error(`Invalid JIRA Story ID: '${storyId}'. Expected format: PROJECT-123`);
}

return [{ json: { story_id: storyId } }];

// Parse JIRA story response
const issue = $input.first().json;

const fields = issue.fields || {};

// Extract description text from Atlassian Document Format (ADF)
function extractText(adf) {
  if (!adf) return '';
  if (typeof adf === 'string') return adf;
  let text = '';
  if (adf.text) text += adf.text;
  if (adf.content && Array.isArray(adf.content)) {
    for (const node of adf.content) {
      text += extractText(node);
      if (['paragraph','heading','listItem','bulletList','orderedList'].includes(node.type)) {
        text += '\n';
      }
    }
  }
  return text;
}

// Extract acceptance criteria from description or custom field
const description = extractText(fields.description);

// Try to find acceptance criteria section
let acceptanceCriteria = '';
const acMatch = description.match(/acceptance criteria[:\s]+([\s\S]*?)(?=\n#|$)/i);
if (acMatch) {
  acceptanceCriteria = acMatch[1].trim();
}

// Try custom field for acceptance criteria (common field IDs)
const customFields = ['customfield_10016', 'customfield_10014', 'customfield_10300'];
for (const cf of customFields) {
  if (fields[cf]) {
    const cfText = extractText(fields[cf]);
    if (cfText) { acceptanceCriteria = cfText; break; }
  }
}

return [{
  json: {
    story_id: issue.key,
    issue_id: issue.id,
    summary: fields.summary || '',
    description: description,
    acceptance_criteria: acceptanceCriteria,
    issue_type: fields.issuetype?.name || '',
    status: fields.status?.name || '',
    priority: fields.priority?.name || ''
  }
}];

// Filter test cases linked to the story
const zephyrResponse = $input.first().json;
const storyData = $('Parse JIRA Story').first().json;

const testCases = zephyrResponse.values || zephyrResponse.testCases || [];
const issueId = storyData.issue_id;
const storyKey = storyData.story_id;

const linkedTestCases = testCases.filter(tc => {
  const links = tc.linkedIssues || tc.issueLinks || tc.links?.issues || [];
  return links.some(link => {
    const id = link.issueId || link.id || '';
    const key = link.issueKey || link.key || '';
    const target = link.target || '';
    return (
      String(id) === String(issueId) ||
      key === storyKey ||
      target.includes(issueId)
    );
  });
});

return [{
  json: {
    story_id: storyKey,
    issue_id: issueId,
    summary: storyData.summary,
    description: storyData.description,
    acceptance_criteria: storyData.acceptance_criteria,
    all_testcases_count: testCases.length,
    linked_testcases: linkedTestCases.map(tc => ({
      key: tc.key || tc.testCaseKey || '',
      name: tc.name || tc.title || '',
      objective: tc.objective || '',
      precondition: tc.precondition || '',
      status: tc.status?.name || tc.statusName || '',
      steps: (tc.testScript?.stepByStepScript?.steps || tc.steps || []).map(s => ({
        description: s.description || '',
        expectedResult: s.expectedResult || ''
      }))
    }))
  }
}];

// Detect duplicate test cases using Jaccard similarity on name and objective.
// Duplicates are removed from the active list; their keys are queued for deletion.
const data = $input.first().json;
const testcases = data.linked_testcases || [];

function normalize(str) {
  return (str || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function jaccardSimilarity(a, b) {
  const tokensA = new Set(normalize(a).split(' ').filter(Boolean));
  const tokensB = new Set(normalize(b).split(' ').filter(Boolean));
  if (tokensA.size === 0 || tokensB.size === 0) return 0;
  const intersection = new Set([...tokensA].filter(x => tokensB.has(x)));
  const union = new Set([...tokensA, ...tokensB]);
  return intersection.size / union.size;
}

// NAME similarity >= 0.75 OR OBJECTIVE similarity >= 0.85 = duplicate
const THRESHOLD_NAME = 0.75;
const THRESHOLD_OBJ  = 0.85;

const duplicateGroups = [];
const toDeleteIndices = new Set();

for (let i = 0; i < testcases.length; i++) {
  if (toDeleteIndices.has(i)) continue;

  const group = {
    keep: testcases[i].key,
    keep_name: testcases[i].name,
    duplicates: []
  };

  for (let j = i + 1; j < testcases.length; j++) {
    if (toDeleteIndices.has(j)) continue;

    const nameSim = jaccardSimilarity(testcases[i].name, testcases[j].name);
    const objSim  = jaccardSimilarity(testcases[i].objective, testcases[j].objective);

    if (nameSim >= THRESHOLD_NAME || objSim >= THRESHOLD_OBJ) {
      group.duplicates.push({
        key: testcases[j].key,
        name: testcases[j].name,
        similarity_score: Math.max(nameSim, objSim).toFixed(2)
      });
      toDeleteIndices.add(j);
    }
  }

  if (group.duplicates.length > 0) {
    duplicateGroups.push(group);
  }
}

const keysToDelete   = [...toDeleteIndices].map(i => testcases[i].key);
const cleanTestcases = testcases.filter((_, i) => !toDeleteIndices.has(i));

return [{
  json: {
    ...data,
    linked_testcases: cleanTestcases,
    duplicate_groups: duplicateGroups,
    keys_to_delete: keysToDelete,
    has_duplicates: keysToDelete.length > 0
  }
}];

// Split the keys_to_delete array into individual items so the
// Delete node processes each one separately.
const data = $input.first().json;
const keysToDelete = data.keys_to_delete || [];

if (keysToDelete.length === 0) return [];

return keysToDelete.map(key => ({ json: { key_to_delete: key } }));

// All duplicate deletions are done. Restore the clean story data
// (with duplicates already removed from linked_testcases) so downstream
// nodes receive a single, authoritative item.
const storyData = $('Detect Duplicates').first().json;
return [{ json: storyData }];

// Parse Claude's coverage analysis response
const claudeResponse = $input.first().json;
const filterData = $('Merge After Dedup').first().json;

let analysisText = claudeResponse.text ||
  claudeResponse.content?.[0]?.text ||
  claudeResponse.message?.content?.[0]?.text ||
  claudeResponse.output?.[0]?.text ||
  JSON.stringify(claudeResponse);

// Strip markdown code fences if present
analysisText = analysisText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

let analysis;
try {
  analysis = JSON.parse(analysisText);
} catch (e) {
  const jsonMatch = analysisText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Failed to parse Claude coverage analysis: ' + analysisText.slice(0, 500));
  }
}

// Only keep HIGH and CRITICAL risk missing scenarios
const filteredMissing = (analysis.missing_scenarios || []).filter(
  s => s.risk_level === 'critical' || s.risk_level === 'high'
);

return [{
  json: {
    ...filterData,
    coverage_summary: analysis.coverage_summary || {},
    missing_scenarios: filteredMissing
  }
}];

