// Extract the created test case key from Zephyr response
const zephyrResponse = $input.first().json;
const inputData = $('Parse New Test Cases').first().json;

const testcaseKey = zephyrResponse.key ||
  zephyrResponse.testCaseKey ||
  zephyrResponse.id ||
  zephyrResponse.testCase?.key;

if (!testcaseKey) {
  throw new Error('Could not extract testcase key from Zephyr response: ' + JSON.stringify(zephyrResponse).slice(0, 300));
}

return [{
  json: {
    testcase_key: testcaseKey,
    testcase_name: inputData.testcase?.name || '',
    issue_id: inputData.issue_id,
    story_id: inputData.story_id,
    project_key: inputData.project_key,
    coverage_summary: inputData.coverage_summary,
    missing_scenarios: inputData.missing_scenarios,
    linked_testcases: inputData.linked_testcases,
    duplicate_groups: inputData.duplicate_groups,
    summary: inputData.summary
  }
}];

// No critical gaps were found — existing tests provide adequate coverage.
// Build a structured output so the final formatter has the same shape
// as the new-tests-created path.
const data = $input.first().json;

return [{
  json: {
    story: {
      id: data.story_id,
      summary: data.summary
    },
    coverage_summary: data.coverage_summary || {},
    existing_testcases: (data.linked_testcases || []).map(tc => ({
      key: tc.key,
      name: tc.name,
      objective: tc.objective
    })),
    missing_scenarios: [],
    new_testcases_created: [],
    duplicates_removed: (data.duplicate_groups || []).map(g => ({
      kept: g.keep,
      kept_name: g.keep_name,
      deleted: g.duplicates.map(d => ({ key: d.key, name: d.name, similarity: d.similarity_score }))
    })),
    status: 'COVERAGE_ADEQUATE',
    message: 'Existing test cases provide sufficient coverage. No new test cases were generated.'
  }
}];

// Aggregate all results into a single structured output.
// Handles both paths:
//   A) New test cases were created (status: NEW_TESTS_CREATED)
//   B) Coverage was already adequate (status: COVERAGE_ADEQUATE)
const allItems = $input.all();
const firstItem = allItems[0]?.json || {};

// Path B: No Gaps Message already built the full output
if (firstItem.status === 'COVERAGE_ADEQUATE') {
  return [{ json: firstItem }];
}

// Path A: Aggregate created test case keys/names
const newTestCasesCreated = allItems.map(item => ({
  key: item.json.testcase_key || '',
  name: item.json.testcase_name || ''
})).filter(tc => tc.key);

const coverageData = $('Parse Coverage Analysis').first().json;

return [{
  json: {
    story: {
      id: coverageData.story_id || '',
      summary: coverageData.summary || ''
    },
    coverage_summary: coverageData.coverage_summary || {},
    existing_testcases: (coverageData.linked_testcases || []).map(tc => ({
      key: tc.key,
      name: tc.name,
      objective: tc.objective
    })),
    missing_scenarios: coverageData.missing_scenarios || [],
    new_testcases_created: newTestCasesCreated,
    duplicates_removed: (coverageData.duplicate_groups || []).map(g => ({
      kept: g.keep,
      kept_name: g.keep_name,
      deleted: g.duplicates.map(d => ({ key: d.key, name: d.name, similarity: d.similarity_score }))
    })),
    status: 'NEW_TESTS_CREATED'
  }
}];
